public class CityStyle2DFigureProvider extends DefaultFigureProvider {

	private static IFigureProvider singleton;

	public IFigure getFigure(Object object) {

		IFigure figure = null;
		Color color = null;
		City rootActGroup = (City) object;
		City cityRule = rootActGroup;

		if (cityRule.getCommunityInfectionStatus() == CommunityInfectionStatusEnum.infectionsObserved) {
			//--ids  [cityRule, cityRuleCommunityInfectionStatusIdenticalInfectionsObservedQuery]

			color = ColorConstants.yellow;

			//--ids  [cityRule, cityRuleCommunityInfectionStatusIdenticalInfectionsObservedQuery, cityRuleColorYellow]
			figure = Shapes.createOval();
			//--ids  [cityRule, cityRuleCommunityInfectionStatusIdenticalInfectionsObservedQuery, cityRuleColorYellow, cityRuleShapeOval]

			((Shape) figure).setFill(true);
			figure.setBackgroundColor(color);

		}
		if (!(cityRule.getCommunityInfectionStatus() == CommunityInfectionStatusEnum.infectionsObserved)) {
			//--ids  [cityRule, cityRuleCommunityInfectionStatusIdenticalInfectionsObservedQuery, not_CityRule_CityRuleOrIdentityOutbreakCityQuery__]

			color = ColorConstants.blue;

			//--ids  [cityRule, cityRuleCommunityInfectionStatusIdenticalInfectionsObservedQuery, not_CityRule_CityRuleOrIdentityOutbreakCityQuery__, cityRuleColorBlue]
			figure = Shapes.createOval();
			//--ids  [cityRule, cityRuleCommunityInfectionStatusIdenticalInfectionsObservedQuery, not_CityRule_CityRuleOrIdentityOutbreakCityQuery__, cityRuleColorBlue, cityRuleShapeOval]

			((Shape) figure).setFill(true);
			figure.setBackgroundColor(color);

		}
		if (cityRule.getCommunityInfectionStatus() == CommunityInfectionStatusEnum.originCity) {
			//--ids  [cityRule, cityRuleCommunityInfectionStatusIdenticalOriginCityQuery]

			color = ColorConstants.gray;

			//--ids  [cityRule, cityRuleCommunityInfectionStatusIdenticalOriginCityQuery, cityRuleColorGray]
			figure = Shapes.createOval();
			//--ids  [cityRule, cityRuleCommunityInfectionStatusIdenticalOriginCityQuery, cityRuleColorGray, cityRuleShapeOval]

			((Shape) figure).setFill(true);
			figure.setBackgroundColor(color);

		}

		return figure;
	}

	public static IFigureProvider getDefault() {
		if (singleton == null) {
			singleton = new CityStyle2DFigureProvider();
		}
		return singleton;
	}
}
